function sheetHTML(subId,pi,key,n,tot){
 const s=SUB[subId],p=PAGES[subId][pi],ur=!!s.rtl,total=PAGES[subId].length;
 return `<div class="sheet s-${subId}${ur?' ur':''}"${ur?' dir="rtl" lang="ur"':''}>
  <div class="sh-top"><span>${ur?'نام':'Name'}<i></i></span><span>${ur?'تاریخ':'Date'}<i></i></span>${key?`<b class="stamp">${ur?'جوابات':'Answer key'}</b>`:''}</div>
  <div class="sh-head"><span class="sh-chip">${ur?'اردو':s.name} · ${p.topic}</span><h2>${p.title}</h2><p class="sh-instr">${p.instr}</p></div>
  <div class="sh-body"><div class="sh-in" style="zoom:${ZOOM[subId+'-'+(pi+1)]||1}">${p.blocks.map(b=>blockHTML(b,key,ur)).join('')}</div></div>
  <div class="sh-foot" dir="ltr"><span class="sh-fl"><b>Little Takhti</b> · ${GR[s.grade].name} · ${s.name} · ${p.en||p.topic}<br>${key?'Answer key':''}${key&&n?' · ':''}${n?`Page ${n} of ${tot}`:''}</span><span class="sh-fq">More free worksheets<br><b>littletakhti.com</b>${SH_QR}</span></div></div>`;
}
const frame=(sub,pi,key,n,tot)=>`<div class="frame">${sheetHTML(sub,pi,key,n,tot)}</div>`;

